/**
 * The committed dataset: validation for both the build-time read (prerendered
 * rows) and the browser fetch, plus the numbers the homepage markup needs.
 *
 * `servers.json` is a build artifact, not a live fetch: the browser cannot
 * build it (CORS blocks both glama.ai and raw.githubusercontent, and GitHub
 * allows only 60 anonymous calls an hour against ~3,000 repos), so the file is
 * generated by `pnpm run build:data`. CI builds without it, so a missing file
 * means "no rows", never a failed build.
 */
import { readFileSync } from "node:fs";

import type { Facets } from "./facets.ts";
import type { Server } from "./server.ts";

import { computeFacets, pushedValues, starValues, ungradedCount } from "./facets.ts";
import { applyFilterSort, DEFAULT_FILTER, DEFAULT_SORT } from "./filter-sort.ts";
import { parseServers } from "./parse-servers.ts";

export const DATA_PATH = "public/servers.json";

/**
 * Reads the dataset at build time; a missing file is an empty list.
 */
export function readServersFile(path = DATA_PATH): Server[] {
  let text: string;
  try {
    text = readFileSync(path, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
  return parseServers(JSON.parse(text));
}

export interface HomeModel {
  readonly categories: readonly string[];
  readonly facets: Facets;
  readonly pushed: readonly number[];
  /**
   * Every server in the default view's order (the order the rows are printed in).
   */
  readonly rows: readonly Server[];
  readonly stars: readonly number[];
  readonly total: number;
  readonly ungraded: number;
}

export function buildHomeModel(servers: readonly Server[]): HomeModel {
  const rows = applyFilterSort(servers, DEFAULT_FILTER, DEFAULT_SORT);
  return {
    categories: [...new Set(servers.flatMap((s) => s.categories))].toSorted((a, b) =>
      a.localeCompare(b),
    ),
    facets: computeFacets(rows),
    pushed: pushedValues(servers),
    rows,
    stars: starValues(servers),
    total: servers.length,
    ungraded: ungradedCount(rows),
  };
}
